        this.rates = rates;
        this.clock = clock;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's figures now. */
    public Snapshot take(String sheet) {
        LocalDate today = clock.today(sheet);
        List<Rate> sheetRates = rates.list(sheet);
        BigDecimal floor = settings.floor(sheet);
        List<Claim> all = claims.list(sheet);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.list(sheet)) {
            List<Claim> mine = all.stream().filter((c) -> c.person() == person.id() && c.counts(person.held())).toList();
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            for (Claim claim : mine) {
                claimed = claimed.add(new BigDecimal(claim.amount()));
                BigDecimal d = claim.due(sheetRates, person.grade(), floor);
                due = d == null ? due : due.add(d);
            }
            // n/a when the grade has no rate on the sheet's today, unless a claim keeps a figure.
            boolean na = Rate.on(sheetRates, person.grade(), today) == null && mine.stream().noneMatch(Claim::fixed);
            claimedTotal = claimedTotal.add(claimed);
            if (!na) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), na ? "n/a" : due.toPlainString()));
        }
        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString());
    }

    /** Audits the figures the change moved since {@code before}, after the change's own lines. */
    public void record(String sheet, String user, Snapshot before) {
        Snapshot after = take(sheet);
        String prefix = " sheet=" + sheet + " by=" + user + " ";
        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
            Figures now = entry.getValue();
            Figures was = before.people().get(entry.getKey());
            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())) {
                audit.record("ROLLUP" + prefix + "person=" + now.name() + " claimed=" + now.claimed() + " due-total="
                        + now.dueTotal());
            }
        }
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
            audit.record("TOTALS" + prefix + "claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal());
        }
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.rate.Rate;

/**
 * A claim as the screen shows it: amount with two decimals, date (ISO yyyy-MM-dd), note, status and its number on
 * the sheet (given when opened and kept once voided; null while a draft), and its due fixed when settled (two decimals;
 * null until settled, and when the grade had no rate then), and the user who opened it (null until opened), and
 * whether its person's last statement bound it, with the figure it bound (null when the grade had no rate then).
 */
public record Claim(long id, long person, String amount, String date, String note, ClaimStatus status,
        Integer number, String settledDue, String openedBy, boolean stated, String statedDue) {

    /** The audit fields of this claim for the named person, as {@link ClaimInput#auditFields}. */
    public String auditFields(String person) {
        return "person=" + person + " amount=" + amount + " date=" + date;
    }

    /** This claim, numbered: its audit fields end with number=<number> when it has one. */
    public Claim withNumber(Integer number) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue);
    }

    /** This claim, settled with its due fixed (null when its grade had no rate). */
    public Claim withSettledDue(String settledDue) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue);
    }

    /** The audit fields of a status change: {@link #auditFields} then number=<number> when it has one. */
    public String statusAuditFields(String person) {
        return auditFields(person) + (number == null ? "" : " number=" + number);
    }

    /** Whether this claim counts toward the totals: OPEN and SETTLED claims do. */
    public boolean counts() {
        return status == ClaimStatus.OPEN || status == ClaimStatus.SETTLED;
    }

    /** Whether this claim counts toward the live totals when its person is {@code held}: then only SETTLED does. */
    public boolean counts(boolean held) {
        return held ? status == ClaimStatus.SETTLED : counts();
    }

    /**
     * Whether this claim keeps a figure whatever the rates: fixed when settled, or bound by a statement (a claim
     * settled or bound when its grade had no rate keeps none).
     */
    public boolean fixed() {
        return settledDue != null || (stated && statedDue != null);
    }

    /**
     * This claim's due: the one fixed when settled, else the one its statement bound, else its amount at the
     * grade's rate in force on its date, raised to at least the sheet's floor; null when there is none.
     */
    public BigDecimal due(List<Rate> rates, String grade, BigDecimal floor) {
        if (settledDue != null) {
            return new BigDecimal(settledDue);
        }
        if (stated) {
            return statedDue == null ? null : new BigDecimal(statedDue);
        }
        BigDecimal live = Rate.due(amount, Rate.on(rates, grade, LocalDate.parse(date)));
        return live == null ? null : live.max(floor);
    }
}
-- The sheet's settings, one row per sheet and key; a key with no row takes its default. The clerk-limit
-- (two decimals) caps the due a clerk may settle; with no row (or a blank one) there is no limit.
CREATE TABLE setting (
    sheet         VARCHAR(200) NOT NULL,
    setting_key   VARCHAR(100) NOT NULL,
    setting_value VARCHAR(200) NOT NULL,
    PRIMARY KEY (sheet, setting_key)
);

